  "root_file": {"line_budget": 100, "budget_declared_in_first_comment": false, "line_count": 480, "within_budget": false, "ci_line_check": false},
  "secrets": {"scanner": "gitleaks", "runs_in_ci": true, "runs_in_pre_commit": false, "clean": false, "referenced_by_name_only": false},
  "commands": [
    {"invocation": "run the tests", "verbatim": false, "exit_code": 1}
  ],
  "imports": {
    "pasted_repo_content": true,
    "entries": [
      {"path": "docs/deep/chain/six/hops/README.md", "exists": true, "hop_depth": 6}
    ]
  },
  "local_scope": {"personal_content_in_committed_file": true, "claude_local_md_gitignored": false},
  "root_has_per_package_commands": true,
  "prohibitions": [
    {"line": "IMPORTANT: never touch the config", "consequence_stated": false, "emphasised": true}
  ],
  "emphasis_ratio": 0.6,
  "refs_check": {"kind": "ci-job", "location": ".github/workflows/claude-md-refs.yml", "all_refs_exist": false},
  "reviewer": "team:platform",
  "evidence": [
    "https://ci.example.com/acme/platform/runs/5119"
  ]
}
